CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans( dim int, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit int ) RETURNS TABLE(moved bigint, sample jsonb) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_moved bigint; v_sample jsonb; v_seg text[]; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- nexus-sa731: EXCLUSIVE half of the RDR-191 sweep gate — the SAME -- advisory-lock key CatalogRepository#acquireSweepGateShared (taken by -- every manifest writer before inserting into catalog_document_chunks) -- and #acquireSweepGateExclusive (taken by runSweepTransaction) use. -- Held for the remainder of this function's transaction: no manifest -- INSERT for THIS (tenant, collection) can commit — or even begin, -- since its own SHARED acquisition blocks on our EXCLUSIVE hold — while -- the guard below is being evaluated. -- -- nexus-sa731 ROUND 2 (code-review-expert T2 [22403] Important finding / -- substantive-critic T2 [22404] Significant finding): the acquisition is -- bounded with the SAME lock_timeout/statement_timeout pair -- acquireSweepGateExclusive itself sets (CatalogRepository.java:3898-3907, -- SWEEP_GATE_LOCK_TIMEOUT_MS=2000 / SWEEP_STATEMENT_TIMEOUT_MS=5000) — an -- unbounded wait here would hang this synchronous HTTP handler -- (VectorHandler#handleGcQuarantineOrphans) indefinitely behind a -- long-running manifest writer (StagingPromoteOps.finalizeTenant is -- documented elsewhere as potentially minutes at real scale), exactly -- the failure direction acquireSweepGateExclusive's own javadoc says the -- gate exists to avoid. lock_timeout bounds the ACQUISITION wait below; -- statement_timeout bounds the HOLD once granted (this function's own -- subsequent statements), same split as the Java model. A -- lock_not_available timeout on the acquisition itself is caught and -- re-raised as an explicit, loud, retryable error naming the gate -- -- nothing has mutated at that point (the PERFORM below is the very -- first statement that could contend), so this is a clean failure, -- never a partial mutation and never a silent success. A -- statement_timeout expiring on a LATER statement (57014, e.g. the -- copy INSERT or the DELETE) is deliberately NOT caught here -- -- PL/pgSQL propagates an uncaught error up through this function, -- which aborts its entire transaction, so no partial mutation can -- survive that path either. PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '5000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'gc_quarantine_orphans: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer is holding it; retry', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
IF dim = 384 THEN -- Pre-flight: is there anything to move at all? Used ONLY to decide -- whether to bother registering the quarantine sibling and running the -- move statements below -- NOT the source of truth for WHICH chashes -- move (that is re-derived independently, inline, by the INSERT and -- DELETE below). Under the EXCLUSIVE gate already held above, nothing -- can change between this check and those statements, so this is -- always consistent with them; it exists only so a zero-candidate -- pass costs one indexed EXISTS instead of an unconditional copy + -- delete + registration attempt. IF NOT EXISTS ( SELECT 1 FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
-- Registration MUST precede the copy INSERT below: chunks_384.collection -- carries a catalog_collections FK, and the pre-flight check above only -- proves there is something to copy, not that the destination exists yet. v_seg := string_to_array(p_quarantine_collection, '__'); INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version) VALUES ( p_tenant_id, p_quarantine_collection, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[1] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[2] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[3] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[4] ELSE '' END ) ON CONFLICT (tenant_id, name) DO NOTHING;
INSERT INTO nexus.chunks_384 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT p_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
RETURN QUERY SELECT v_moved, v_sample; RETURN;
ELSIF dim = 768 THEN -- See dim=384's identical pre-flight comment above. IF NOT EXISTS ( SELECT 1 FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
v_seg := string_to_array(p_quarantine_collection, '__'); INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version) VALUES ( p_tenant_id, p_quarantine_collection, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[1] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[2] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[3] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[4] ELSE '' END ) ON CONFLICT (tenant_id, name) DO NOTHING;
INSERT INTO nexus.chunks_768 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT p_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
RETURN QUERY SELECT v_moved, v_sample; RETURN;
ELSIF dim = 1024 THEN -- See dim=384's identical pre-flight comment above. IF NOT EXISTS ( SELECT 1 FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
v_seg := string_to_array(p_quarantine_collection, '__'); INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version) VALUES ( p_tenant_id, p_quarantine_collection, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[1] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[2] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[3] ELSE '' END, CASE WHEN array_length(v_seg, 1) = 4 THEN v_seg[4] ELSE '' END ) ON CONFLICT (tenant_id, name) DO NOTHING;
INSERT INTO nexus.chunks_1024 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT p_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
RETURN QUERY SELECT v_moved, v_sample; RETURN; END IF; END; $$

